__NUXT_JSONP__("/ru/promo_material/thanks", (function(a){return {data:[{details:{slug:"ru",pageTitle:"Promo - Thanks Download Brochure | Mentor Language Institute",pageDescription:"Скачайте брошюру, используя ссылки ниже",title:"Promo - Thanks Download Brochure",subtitle:["Скачайте брошюру, используя ссылки ниже:"],brochures:[{title:"Приветственная акция 2022 года",image:"\u002Fimages\u002Fmaterial\u002F1642409014-WELCOME_Promotion_RUSSIAN_JAN13.jpg",link_text:a,link:"\u002Fassets\u002Fimages\u002Fmaterial\u002F1642409014-WELCOME_Promotion_RUSSIAN_JAN13.jpg"},{title:"Школьная брошюра",image:"\u002Fimages\u002Fmaterial\u002Fmli-brochure-program-schedule-en.png",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002FMLI School Brochure.pdf"},{title:"Брошюра проживания",image:"\u002Fimages\u002Fmaterial\u002F2022-housing-brochure.png",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002FUSSS Student Housing Brochure(updated 10.16.2024).pdf"},{title:"2026 Цены и предложения при подаче заявки",image:"\u002Fimages\u002Fmaterial\u002F2026-price-package.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2026 MLI Info Pack updated_9.17.25.pdf"},{title:"Брошюра мероприятий MLI",image:"\u002Fimages\u002Fmaterial\u002F2027 MLI Activity.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2027 MLI Activity Calendar Brochure 10.1.26.pdf"}],other_info:["\u003Cspan class='hutoaka'\u003EСотрудники приемной комиссии отправят вам электронное письмо по поводу вашего запроса.\u003C\u002Fspan\u003E\u003Cbr \u002F\u003EЕсли у вас есть какие-либо вопросы относительно студенческих виз, вариантов проживания или чего-либо еще, пожалуйста, свяжитесь с нами в любое время.","Процесс обучения за границей в Соединенных Штатах очень сложен, мы можем проконсультировать вас по телефону.","Если вы не отметили «Не связываться со мной по телефону», мы позвоним вам через 1-2 дня.","\u003Cb\u003E【кампус WESTWOOD】\u003C\u002Fb\u003E\u003Cbr \u002F\u003E10880 Wilshire Blvd., офис122\u003Cbr \u002F\u003ELos Angeles, CA 90024\u003Cbr \u002F\u003EТЕЛ: ＋1（310）887-0777\u003Cbr \u002F\u003EE-mail: info@mliesl.edu\u003Cbr \u002F\u003EЧасы работы: с понедельника по четверг с 8:30 до 20:30, в пятницу с 8:30 до 18:00.","\u003Cb\u003E【кампус HOLLYWOOD】\u003C\u002Fb\u003E\u003Cbr \u002F\u003E7080 Hollywood Blvd., офис314\u003Cbr \u002F\u003ELos Angeles, CA 90028\u003Cbr \u002F\u003EТЕЛ: ＋1（323）870-7102\u003Cbr \u002F\u003EE-mail: hollywood@mliesl.edu\u003Cbr \u002F\u003EЧасы работы: с понедельника по пятницу с 8:30 до 17:00"],dir:"\u002Fpromo-material-thanks",path:"\u002Fpromo-material-thanks\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:30.780Z",updatedAt:"2026-10-06T17:46:57.888Z"}}],fetch:{},mutations:void 0}}("\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E Download")));